import{_ as i,o as a,c as e,ah as l}from"./chunks/framework.Bv6G8Ib6.js";const d="data:image/svg+xml;base64,",m="/arch-guidelines/assets/review_d_ladder.CgdvQwbS.svg",g="/arch-guidelines/assets/review_c_questions.Cjwry0HT.svg",Z=JSON.parse('{"title":"レビュー技術","description":"","frontmatter":{"sidebarDepth":4,"title":"レビュー技術","author":"フューチャー株式会社","search":false,"head":[["meta",{"name":"robots","content":"noindex, nofollow"}]]},"headers":[],"relativePath":"documents/forSoftSkill/consensus/review.md","filePath":"documents/forSoftSkill/consensus/review.md"}'),M={name:"documents/forSoftSkill/consensus/review.md"};function o(j,I,h,s,t,r){return a(),e("div",null,[...I[0]||(I[0]=[l('<h1 id="レビュー技術" tabindex="-1">レビュー技術 <a class="header-anchor" href="#レビュー技術" aria-label="Permalink to &quot;レビュー技術&quot;">​</a></h1><p>レビューの役割は、資料の良し悪しを判定することではなく、メンバーが手続きのどこで詰まっているかを見極め、次に何を考えればよいかを伝えることである。</p><h2 id="レビューでの見極め方" tabindex="-1">レビューでの見極め方 <a class="header-anchor" href="#レビューでの見極め方" aria-label="Permalink to &quot;レビューでの見極め方&quot;">​</a></h2><p>レビューを始める前に、メンバーの成果物がどの段階にあるかを見極める。</p><p><img src="'+d+'" alt="レビューでの見極め方" width="1560" height="358"></p><h3 id="_1比較表が出てきたところが、指導の出発点" tabindex="-1">①比較表が出てきたところが、指導の出発点 <a class="header-anchor" href="#_1比較表が出てきたところが、指導の出発点" aria-label="Permalink to &quot;①比較表が出てきたところが、指導の出発点&quot;">​</a></h3><p>最初のレビューは、仮の比較表と推奨案ができた時点で行う。そこまでは経験の浅いメンバーでも AI を使って作れ、指導が要るのはその先だからである。</p><h3 id="_2比較表のレビューでは、中身より観点の妥当性を見る" tabindex="-1">②比較表のレビューでは、中身より観点の妥当性を見る <a class="header-anchor" href="#_2比較表のレビューでは、中身より観点の妥当性を見る" aria-label="Permalink to &quot;②比較表のレビューでは、中身より観点の妥当性を見る&quot;">​</a></h3><p>初期段階では、✅⚠️❌を精緻に埋めさせず、観点が妥当か、相手の関心事に合っているかを先に確かめる。</p><ul><li>観点がずれていると、✅⚠️❌を正確に埋めた調査や検証が手戻りになる</li><li>仮の✅⚠️❌なら、一部が空白でも、優劣の傾向と、どこが論点になりそうかは掴める</li></ul><p>観点を分類する軸（QCD や品質特性など）は、最初はレビュアーが示す。</p><h3 id="_3落としどころを語れるかで見極める" tabindex="-1">③落としどころを語れるかで見極める <a class="header-anchor" href="#_3落としどころを語れるかで見極める" aria-label="Permalink to &quot;③落としどころを語れるかで見極める&quot;">​</a></h3><p>観点を確かめたら、「なぜこの案を推奨するのか」と聞く。「要件が◯◯だと仮定すれば、△△の観点でこの案がよい」と自分の言葉で言えればよい。言えなければ、闇雲に進めている懸念がある。相手に持っていく前に、チーム内で仮説を立て直す。</p><p><img src="'+m+'" alt="③落としどころを語れるかで見極める" width="1560" height="972" loading="lazy"><em>覚悟の問題に見えるもの</em></p><p>図の①は、役割分担が曖昧なプロジェクト初期に起きやすい。図の②と③は、進め方の指導で解ける。図の④は、道筋も相手の事情も見えているのに、自分のスタンスを決められない状態である。自分ならどれを、何を理由に選ぶかを言わせる。</p><h3 id="_4目的は、ドラフトの後で言葉にさせる" tabindex="-1">④目的は、ドラフトの後で言葉にさせる <a class="header-anchor" href="#_4目的は、ドラフトの後で言葉にさせる" aria-label="Permalink to &quot;④目的は、ドラフトの後で言葉にさせる&quot;">​</a></h3><p>メンバーはまず中身を作るので、リード文が「違和感はあるか」「Aで進めてよいか」という作成者目線になるのは自然である。ドラフトを見た後で、目的を言葉にし直すステップを設ける。</p><ol><li>ドラフトを見て、相手からどんな質問や反論が出そうか、どこで合意が詰まりそうかを想像する</li><li>該当ページで相手に求めるアクションを、5形式（→Appendixの、相手へのコミュニケーションは、5形式に分類できる）から選び直す</li><li>定義した目的に合わせて、ページ構成やメッセージラインを組み直す</li></ol><p>最低でも、ページごとに「このページの意図は◯◯です」と一文を付箋で書いてもらう。非機能要件の基礎数値を集めるページなら、「見積もりの費用計算、非機能のテストケース、監視設計に使うため」と書いてあれば、相手はそのページの位置づけと重要度が分かる。</p><h2 id="アンチパターン" tabindex="-1">アンチパターン <a class="header-anchor" href="#アンチパターン" aria-label="Permalink to &quot;アンチパターン&quot;">​</a></h2><p>レビュアーが言いがちだが、メンバーの手を止めてしまう声かけを挙げる。①②は特定の段階で、③〜⑤はどの段階でも出やすい。</p><p><img src="'+g+'" alt="アンチパターン" width="1560" height="592" loading="lazy"></p><h3 id="_1「まず導入から書いて」「比較表は作らずに、結論1枚でまず作って」" tabindex="-1">①「まず導入から書いて」「比較表は作らずに、結論1枚でまず作って」 <a class="header-anchor" href="#_1「まず導入から書いて」「比較表は作らずに、結論1枚でまず作って」" aria-label="Permalink to &quot;①「まず導入から書いて」「比較表は作らずに、結論1枚でまず作って」&quot;">​</a></h3><p>どちらも、ベテランが無意識にやっていることをそのまま指導に持ち込んでいる。導入は中身の解像度が上がってから書けるもので、先に書かせると、書き出した仮説に縛られて中身が進まなくなる。比較表を省けるのは、省いた分を知見と相手との信頼で補える人だけである（→ベテランの視点の、手続きを省けるのは、省いた分を信頼で埋められる人だけ）。</p><p>9つの手続きを順に踏ませる。まず手を動かせる具体を作らせ、何が論点になるかを一緒に見極める。</p><h3 id="_2「ここは◯評価じゃなくて△が良いのでは-」" tabindex="-1">②「ここは◯評価じゃなくて△が良いのでは？」 <a class="header-anchor" href="#_2「ここは◯評価じゃなくて△が良いのでは-」" aria-label="Permalink to &quot;②「ここは◯評価じゃなくて△が良いのでは？」&quot;">​</a></h3><p>細部の採点を直させると、メンバーは表を埋める作業に没頭し、相手への翻訳に頭が回らなくなる（→レビューでの見極め方の、②比較表のレビューでは、中身より観点の妥当性を見る）。</p><p>「◯△×は仮でいい。この表を相手が読める大分類に束ねると何になる？」と、手続き5 の翻訳へ視点を上げる。明らかに間違っている部分はさっと伝えるか非同期でコメントする。</p><p>関連する手続き: 手続き4-2、5</p><h3 id="_3「で、論点は何-」と抽象的に詰める" tabindex="-1">③「で、論点は何？」と抽象的に詰める <a class="header-anchor" href="#_3「で、論点は何-」と抽象的に詰める" aria-label="Permalink to &quot;③「で、論点は何？」と抽象的に詰める&quot;">​</a></h3><p>論点という言葉は抽象度が高く、慣れないメンバーは手が止まる。論点は案を比べた差から生まれるので、手前の整理がないまま問うても出てこない。</p><p>「案は何通りある？」「それぞれで何が変わる？」と、前提となる事実確認から問う。比較表ができていれば、「この表で、相手の価値判断が必要なのはどの行？」「それが決まらないと、自分たちの作業は止まる？」「それが決まると、だれがどう嬉しい？」と問い、相手に問うものと報告で済むものを分けさせる。</p><p>関連する手続き: 手続き3、4、6</p><h3 id="_4決断を促そうとして「仮説は何-」と聞く" tabindex="-1">④決断を促そうとして「仮説は何？」と聞く <a class="header-anchor" href="#_4決断を促そうとして「仮説は何-」と聞く" aria-label="Permalink to &quot;④決断を促そうとして「仮説は何？」と聞く&quot;">​</a></h3><p>「仮説」は抽象度が高い言葉で、何を仮説と呼ぶかの基準が無い。本人なりの考えはあるので、「それは仮説ではない」「仮説です」の押し問答になりやすい。仮説という言葉は使わず、何についての考えを聞きたいのかを、資料の状況に合わせて具体的に問う。</p><ul><li>作成途中なら、「ここまでよく作ったね。この後どうしたい？」と受け止めてから問う</li><li>前提が分からず手が止まっているなら、「どういう前提で作ろうとしている？」と問う</li><li>資料ができていれば、「打合せ当日、相手にどう説明する？」と問う。説明の場面を考えると、指摘しなくても自分から直す箇所を挙げてくる</li><li>懸念が見えているなら、「その懸念に対して、どういうストーリーなら納得させられると思った？」と問う</li></ul><p>相手の気持ちの仮説すら立たない状態なら、過去プロジェクトのお手本を渡す。</p><p>関連する手続き: 手続き2-3</p><h3 id="_5「相手目線で考えて」「相手がその上司を説得できるように書いて」「もっと分かりやすく」" tabindex="-1">⑤「相手目線で考えて」「相手がその上司を説得できるように書いて」「もっと分かりやすく」 <a class="header-anchor" href="#_5「相手目線で考えて」「相手がその上司を説得できるように書いて」「もっと分かりやすく」" aria-label="Permalink to &quot;⑤「相手目線で考えて」「相手がその上司を説得できるように書いて」「もっと分かりやすく」&quot;">​</a></h3><p>いずれも目指す状態であって、考え方ではない。足りないのが、目的、評価軸、コンセプト別の選択肢、推奨案、ストーリーのどれなのかを特定して伝える。</p><p>関連する手続き: 手続き5、6-3、7-1</p>',41)])])}const c=i(M,[["render",o]]);export{Z as __pageData,c as default};
